window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-58a6235fb6c23b5d"]={"versions": [{"id": "FIG-58a6235fb6c23b5d", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion im AUTOSAR-Kommunikationsstack während der Bus-Off-Recovery. Dargestellt ist das Abschalten des RX-Deadline-Monitorings zwischen dem CAN State Manager (<code>CanSM</code>) und dem Communication-Modul (<code>Com</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten sind das Modul <code>Com::Com</code> und das Modul <code>CanSM::CanSM</code> (jeweils mit Stereotyp <code>«module»</code>). Aufgerufene Schnittstelle ist die Funktion <code>Com_DisableReceptionDM</code> mit dem Parameter <code>IpduGroupId := CANSM_RX_PDU_GROUP_ID</code>. Die Interaktion wird durch den Konfigurationsparameter <code>CANSM_BOR_DISABLE_RX_DL_MONITORING</code> gesteuert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Innerhalb eines optionalen Fragments (<code>opt Disabling of RX Timeouts during bus off recovery</code>) wird die Ausführungsbedingung <code>[CANSM_BOR_DISABLE_RX_DL_MONITORING == true]</code> evaluiert. Ist diese erfüllt, erfolgt der Funktionsaufruf <code>Com_DisableReceptionDM(IpduGroupId := CANSM_RX_PDU_GROUP_ID)</code> mit anschließender Rückkehr (dargestellt als gestrichelter Pfeil) zum Aufrufer.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevante Implementierungsvorschrift für das Verhalten des CanSM bei Bus-Off: Sofern die Vorkompilierungs- bzw. Konfigurationsoption <code>CANSM_BOR_DISABLE_RX_DL_MONITORING</code> aktiviert ist, muss die Empfangs-Deadline-Überwachung der betroffenen I-PDU-Gruppe über das Com-Modul deaktiviert werden, um fehlerhafte Timeout-Meldungen während des Wiederanlaufs nach einem Bus-Off zu unterbinden. Bezeichner und Parameterzuweisung entsprechen der AUTOSAR-SWS-Konvention.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b74107ae926cdac8", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Interaktion im AUTOSAR-Kommunikationsstack während der Bus-Off-Recovery. Dargestellt ist das Abschalten des RX-Deadline-Monitorings zwischen dem CAN State Manager (<code>CanSM</code>) und dem Communication-Modul (<code>Com</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Komponenten sind das Modul <code>Com::Com</code> und das Modul <code>CanSM::CanSM</code> (jeweils mit Stereotyp <code>«module»</code>). Aufgerufene Schnittstelle ist die Funktion <code>Com_DisableReceptionDM</code> mit dem Parameter <code>IpduGroupId := CANSM_RX_PDU_GROUP_ID</code>. Die Interaktion wird durch den Konfigurationsparameter <code>CANSM_BOR_DISABLE_RX_DL_MONITORING</code> gesteuert.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Innerhalb eines optionalen Fragments (<code>opt Disabling of RX Timeouts during bus off recovery</code>) wird die Ausführungsbedingung <code>[CANSM_BOR_DISABLE_RX_DL_MONITORING == true]</code> evaluiert. Ist diese erfüllt, erfolgt der Funktionsaufruf <code>Com_DisableReceptionDM(IpduGroupId := CANSM_RX_PDU_GROUP_ID)</code> mit anschließender Rückkehr (dargestellt als gestrichelter Pfeil) zum Aufrufer.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevante Implementierungsvorschrift für das Verhalten des CanSM bei Bus-Off: Sofern die Vorkompilierungs- bzw. Konfigurationsoption <code>CANSM_BOR_DISABLE_RX_DL_MONITORING</code> aktiviert ist, muss die Empfangs-Deadline-Überwachung der betroffenen I-PDU-Gruppe über das Com-Modul deaktiviert werden, um fehlerhafte Timeout-Meldungen während des Wiederanlaufs nach einem Bus-Off zu unterbinden. Bezeichner und Parameterzuweisung entsprechen der AUTOSAR-SWS-Konvention.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-58a6235fb6c23b5d", "to": "FIG-b74107ae926cdac8", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
